type Envelope struct {
    Type    string          `json:"type"`
    Payload json.RawMessage `json:"payload"`
}

var handlers = map[string]func(json.RawMessage) error{"reserve-stock": reserveStock}

func handle(e Envelope) error {
    h, ok := handlers[e.Type]          // unknown tag is an application error, not a panic
    if !ok { return fmt.Errorf("unknown command %q", e.Type) }
    return h(e.Payload)
}
